import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In the coordinate plane, consider a convex equilateral hexagon ABCDEF with AB ∥ DE, BC ∥ EF, CD ∥ FA, and ∠FAB = 120°. Assume that moving from A to B increases the y-coordinate by {step}, and moving from A to C (two consecutive edges of the hexagon) increases the y-coordinate by {rise_ac}·{step}. The y-coordinates of A, B, C, D, E, and F are pairwise distinct. The area of ABCDEF can be expressed in the form m√n, where m and n are positive integers and n is squarefree. Determine m + n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose step and rise_ac ensuring nontrivial values and a moderate answer size
# step > 1, rise_ac > 1 to avoid degenerate/too-easy cases.
for _ in range(100):
    step = rng.randint(2, 12)
    rise_ac = rng.randint(2, 8)
    m = step*step * (1 + (rise_ac - 1)**2 + rise_ac**2)
    n = 3
    ans = m + n
    # Keep answer within a reasonable contest range and nontrivial
    if 50 <= ans <= 10000:
        return {"step": step, "rise_ac": rise_ac}
# Fallback in the unlikely event the loop doesn't return
return {"step": 6, "rise_ac": 5}

    def verifier(assign):
# Validate domain constraints and compute the numeric answer.
# Geometry rationale (informal, see notes for proof):
# Let the three equal-length side direction vectors be v1, v2, v3 with pairwise angles 120° and v1+v2+v3=0.
# Denote their y-components by y1, y2, y3. Given that AB has y-rise step, y1 = step.
# Given AC (two edges) has y-rise rise_ac*step, we have y1 + y2 = rise_ac*step, so y2 = (rise_ac - 1)*step.
# Since v1+v2+v3=0, the y-components satisfy y1+y2+y3=0, hence y3 = -rise_ac*step.
# The area of the 3-direction equilateral hexagon is |v1×v2| + |v2×v3| + |v3×v1| = 3*(sqrt(3)/2)*s^2,
# and s^2 = (2/3)*(y1^2 + y2^2 + y3^2). Therefore area = sqrt(3)*(y1^2 + y2^2 + y3^2).
# This yields m = (y1^2 + y2^2 + y3^2) and n = 3.
try:
    step = assign.get("step", None)
    rise_ac = assign.get("rise_ac", None)
    if not isinstance(step, int) or not isinstance(rise_ac, int):
        # Invalid types
        return (False, None)
    if step <= 1 or rise_ac <= 1:
        # Enforce nontriviality
        return (False, None)
    y1 = step
    y2 = (rise_ac - 1) * step
    y3 = -rise_ac * step
    m = y1*y1 + y2*y2 + y3*y3
    n = 3
    answer = m + n
    # Additional sanity: keep answer in a reasonable range
    if answer < 50:
        return (False, None)
    return True, answer
except Exception:
    return (False, None)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

